310	// Read the known audit file — the second test-assertion channel alongside the UI. The app appends
311	// one record per line; specs filter it by their sheet id. Path comes from AUDIT_FILE (set by
312	// bin/start / bin/e2e); falls back to the app's default.
313	const AUDIT_FILE = process.env.AUDIT_FILE ?? '../.run/audit.log';
314	
315	/** All audit records currently in the file, one per element (empty if none). */
316	export function auditLines(): string[] {
317	  return existsSync(AUDIT_FILE)
318	    ? readFileSync(AUDIT_FILE, 'utf8').split('\n').filter((l) => l.length > 0)
319	    : [];
320	}
