322	// Usage in a spec (audit-category test):
323	//   expect(auditLines()).toContain('OWNER_CREATED id=1 name=Acme');
324	package net.officefloor.hq.app;
325	
326	import java.io.IOException;
327	import java.io.UncheckedIOException;
328	import java.nio.charset.StandardCharsets;
329	import java.nio.file.Files;
330	import java.nio.file.Path;
331	import java.nio.file.StandardOpenOption;
332	import org.springframework.beans.factory.annotation.Value;
333	import org.springframework.stereotype.Service;
334	
335	/**
336	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
337	 * so tests can assert side-effects by reading that file — the second test-assertion channel
338	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
339	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
340	 *
341	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
342	 * SYNC) so a test reads the record immediately.
343	 */
344	@Service
345	public class Audit {
346	
347	    private final Path file;
348	
349	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
350	        this.file = Path.of(path);
351	    }
352	
353	    /** Append one audit record. Tests assert the exact line(s) in the file. */
354	    public synchronized void record(String entry) {
355	        try {
356	            Path parent = file.toAbsolutePath().getParent();
357	            if (parent != null) {
358	                Files.createDirectories(parent);
359	            }
360	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
361	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
362	        } catch (IOException e) {
363	            throw new UncheckedIOException(e);
364	        }
365	    }
366	
367	    /** Remove the audit file. */
368	    public synchronized void clear() {
369	        try {
370	            Files.deleteIfExists(file);
371	        } catch (IOException e) {
372	            throw new UncheckedIOException(e);
373	        }
374	    }
375	}
